import { it, expect } from "vitest";
import { writeFileSync } from "node:fs";
import { ownershipStrength, preservesOwnership } from "@/domain/profileIntake/CareerWritingQuality";
import { runRuleFactGuard } from "@/domain/adaptation/factGuard";
import { classifyJobKeywords } from "@/domain/resumeComposition/ResumeBlueprint";
import type { JobDescription, ResumeItemV2 } from "@/domain/schemas";
import type { ResumeEvidenceGraph } from "@/domain/resumeComposition/contracts";

it("records isolated current helper behavior, not model quality", () => {
  const ownership = ["协助", "参与", "共同完成", "共同负责", "主要负责", "负责", "独立完成", "主导"].map(text => ({ text, strength: ownershipStrength(text) }));
  const guard = (originalText: string, checkedText: string) => runRuleFactGuard({ originalText, checkedText, usedEvidenceRefs: [] }).status;
  const mapping = (keyword: string, text: string) => {
    const item = { id: "audit-asset", sectionType: "project", name: "合成审计", tools: [], highlights: [text], outcomes: [], customFields: [] } as unknown as ResumeItemV2;
    const graph = { sourceAssetIds: [item.id], nodes: [{ id: `asset:${item.id}`, sourceAssetIds: [item.id], factIds: ["audit-fact"], sourceExcerpts: [text] }] } as unknown as ResumeEvidenceGraph;
    const job = { requirements: [{ keywords: [keyword], description: keyword }], rawText: keyword } as unknown as JobDescription;
    return classifyJobKeywords(job, graph, new Map([[item.id, item]])).find(row => row.keyword === keyword)?.status;
  };
  const results = {
    ownership,
    coOwnerToOwner: preservesOwnership("共同负责接口测试", "负责接口测试"),
    mixedSubject: preservesOwnership("负责人主导项目，我协助接口测试", "我主导接口测试"),
    assistToLeadGuard: guard("协助接口测试", "主导接口测试"),
    ownerToLeadGuard: guard("负责接口测试", "主导接口测试"),
    fabricatedPercentageGuard: guard("参与接口测试", "参与接口测试，准确率99%"),
    fabricatedLatencyGuard: guard("负责接口测试", "负责接口测试，延迟80ms"),
    exact: mapping("React", "使用React开发页面"),
    synonymOnly: mapping("Prompt Engineering", "参与提示词工程，验证模型输出"),
    falseSubstring: mapping("Java", "使用JavaScript开发页面"),
    adjacent: mapping("PostgreSQL", "使用SQLite实现数据查询"),
    unknown: mapping("Kubernetes", "使用React开发页面")
  };
  writeFileSync(".tmp/sq13-isolated-helpers.json", JSON.stringify(results, null, 2));
  expect(results.assistToLeadGuard).toBe("blocked_high_risk");
  expect(results.exact).toBe("SUPPORTED");
});
